export function createUpdatesUI({e,api,ui,link}){let current=null,stamp=0;
 const names={material:'Class materials',unit:'Course units',help:'Private help',work:'Classwork',feedback:'Feedback',announcement:'Announcements',portfolio:'Portfolios',discussion:'Discussion topics',reply:'My replies',conversation:'Discussion responses',marking:'Marking',moderation:'Reply approvals',calendar:'Class events'};
 const date=v=>v?new Date(v).toLocaleDateString('en-GB',{day:'numeric',month:'short'}):'';
 async function page(params){const q=new URLSearchParams();for(const k of ['classId','kind','offset','search'])if(params.get(k))q.set(k,params.get(k));const filter=params.get('filter')||'unread';if(filter==='unread'||filter==='read')q.set('read',filter);if(filter==='actionable')q.set('actionable','1');const d=await api('updates?'+q);current=d;const paging={view:'updates',filter,...(params.get('classId')?{classId:params.get('classId')}:{}),...(params.get('kind')?{kind:params.get('kind')}:{}),...(params.get('search')?{search:params.get('search')}:{})},staff=ui.actor().role!=='student';
  return '<nav class="course-progress-tabs" aria-label="Updates and private help">'+link('Updates',{view:'updates'}).replace('<a ','<a aria-current="page" ')+link(staff?'Help requests':'My help requests',{view:'help'})+'</nav><div class="learning-section-title"><h2>Your updates</h2><div class="updates-count"><strong>'+d.unread+' unread</strong>'+(staff?'<span>'+d.actionable+' items need your review</span>':'')+'<button type="button" class="btn" id="updates-refresh">Refresh</button></div></div><p>'+(staff?'Review submissions, portfolio entries and discussion replies from one place. Marking an update read does not complete the review.':'New work, feedback, announcements and class changes. Open the linked page to read the details or take action.')+'</p><form id="updates-filters" class="community-filters"><label>Show <select name="filter">'+[['unread','Unread'],['all','All updates'],...(staff?[['actionable','Needs my review']]:[]),['read','Read']].map(([v,t])=>'<option value="'+v+'" '+(filter===v?'selected':'')+'>'+t+'</option>').join('')+'</select></label><label>Class <select name="classId"><option value="">All my classes</option>'+d.classes.map(c=>'<option value="'+e(c.id)+'" '+(params.get('classId')===c.id?'selected':'')+'>'+e(c.name)+'</option>').join('')+'</select></label><label>Type <select name="kind"><option value="">All types</option>'+d.kinds.map(k=>'<option value="'+e(k)+'" '+(params.get('kind')===k?'selected':'')+'>'+e(names[k]||k)+'</option>').join('')+'</select></label><label>Find <input name="search" maxlength="120" placeholder="Title or student name" value="'+e(params.get('search')||'')+'"></label></form><div class="learning-section-title"><p class="muted">'+d.total+' matching updates'+(d.total?' · '+(d.offset+1)+'–'+Math.min(d.offset+d.limit,d.total):'')+'</p>'+(d.items.some(r=>r.unread)?'<button type="button" class="btn" id="updates-read-page">Mark this page read</button>':'')+'</div><div class="updates-list">'+d.items.map((r,i)=>(i===6?'<details class="updates-more"><summary>Show '+(d.items.length-6)+' more on this page</summary><div class="updates-list">':'')+'<article class="vle-panel update-row '+(r.unread?'update-unread':'')+'"><div class="update-copy"><div class="update-meta"><span class="learning-tag">'+e(names[r.kind]||r.kind)+'</span>'+(r.actionable?'<b>Needs review</b>':'')+'<small>'+e(date(r.when))+'</small></div><h3>'+link(r.title,r.target)+'</h3><p>'+e(r.detail)+'</p><small>'+e(r.className)+'</small></div><div class="update-actions">'+link(r.actionable?'Open for review →':'Open →',r.target)+'<button type="button" class="text-button" data-update-toggle="'+i+'">'+(r.unread?'Mark read':'Mark unread')+'</button></div></article>'+ (i===d.items.length-1&&d.items.length>6?'</div></details>':'')).join('')+(!d.items.length?'<div class="learning-empty"><h3>'+ (filter==='unread'?(d.unread?'No unread updates match these filters.':'You have read all your updates.'):filter==='actionable'?'No reviews waiting in this view.':'No updates match these filters.')+'</h3><p>'+link('See all updates',{view:'updates',filter:'all'})+' · '+link('Back to Today',{view:'today'})+'</p></div>':'')+'</div><nav class="updates-pagination" aria-label="Updates pages">'+(d.offset?link('← Previous page',{...paging,offset:Math.max(0,d.offset-d.limit)}):'')+(d.offset+d.limit<d.total?link('Next page →',{...paging,offset:d.offset+d.limit}):'')+'</nav><p class="muted">Updates are shown here in Classroom. No email or push notifications are sent.</p>';
 }
 function bind(root){const pageData=current;root.querySelector('#updates-refresh')?.addEventListener('click',()=>ui.render());const token=++stamp;api('updates-summary').then(d=>{if(token!==stamp||!root.isConnected)return;const badge=root.querySelector('[data-update-badge]');if(badge){badge.textContent=d.unread?' ('+d.unread+')':'';badge.closest('a').setAttribute('aria-label','Updates'+(d.unread?' · '+d.unread+' unread':''));}}).catch(()=>{});root.querySelector('#updates-filters')?.addEventListener('submit',ev=>{ev.preventDefault();location.hash='/classroom?'+new URLSearchParams({view:'updates',...Object.fromEntries(new FormData(ev.currentTarget))});});root.querySelector('#updates-filters')?.addEventListener('change',ev=>{location.hash='/classroom?'+new URLSearchParams({view:'updates',...Object.fromEntries(new FormData(ev.currentTarget))});});const save=async(items,read,b)=>{b.disabled=true;try{await api('updates-read',{items:items.map(r=>({id:r.id,version:r.version})),read});ui.render();}catch(error){ui.toast(error.message);b.disabled=false;}};root.querySelectorAll('[data-update-toggle]').forEach(b=>b.addEventListener('click',()=>{const r=pageData.items[Number(b.dataset.updateToggle)];save([r],r.unread,b);}));root.querySelector('#updates-read-page')?.addEventListener('click',ev=>save(pageData.items.filter(r=>r.unread),true,ev.currentTarget));}
 return{page,bind};
}
